package ro.leo.visual;
import ro.leo.i18n.L;import android.content.*;import android.os.Bundle;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;
public final class WebAppsActivity extends LeoActivity {
 protected void onCreate(Bundle state){super.onCreate(state);worker.execute(new Runnable(){public void run(){try{WebAppPackages.stock(WebAppsActivity.this);}catch(Exception ignored){}ui(new Runnable(){public void run(){show();String path=getIntent().getStringExtra("web_package");if(path!=null){getIntent().removeExtra("web_package");confirmInstall(new File(path));}}});}});}
 void show(){final ArrayList<JSONObject> apps=WebAppPackages.apps(WebAppsActivity.this);ArrayList<String> labels=new ArrayList<String>();for(JSONObject m:apps)labels.add(m.optString("name")+"\nHTML · offline");list(L.t("Aplicații web Leo"),labels,0,new Choice(){public void pick(final int n){startActivity(new Intent(WebAppsActivity.this,WebRuntimeActivity.class).putExtra("web_app",apps.get(n).optString("id")).addFlags(Intent.FLAG_ACTIVITY_NEW_DOCUMENT));}},L.t("Opțiuni"),new Runnable(){public void run(){options(L.t("Aplicații web Leo"),new String[]{L.t("Importă pachet ZIP"),L.t("Despre runtime"),L.t("Elimină aplicația selectată")},new Choice(){public void pick(final int n){if(n==0)startActivityForResult(new Intent(WebAppsActivity.this,FilesActivity.class).putExtra("pick_web",true),93);else if(n==1)notice(L.t("Aplicații HTML locale, fără acces la rețea sau servicii Android. Datele web se păstrează separat pe aplicație."));else{int at=0;for(int k=0;k<root.getChildCount();k++)if(root.getChildAt(k) instanceof ListView)at=Math.max(0,((ListView)root.getChildAt(k)).getSelectedItemPosition());if(apps.isEmpty())return;final String id=apps.get(Math.min(at,apps.size()-1)).optString("id");options(L.t("Elimini aplicația?"),new String[]{L.t("Păstrează"),L.t("Elimină")},new Choice(){public void pick(final int yes){if(yes==1){UpdateEngine.delete(new File(WebAppPackages.base(WebAppsActivity.this),id));android.webkit.WebStorage.getInstance().deleteOrigin("https://"+id+".apps.leo.invalid");show();}}});}}});}});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==93&&result==RESULT_OK&&data!=null&&data.getStringExtra("file")!=null)confirmInstall(new File(data.getStringExtra("file")));}
 void confirmInstall(final File zip){options(L.t("Importă pachet web")+" · "+zip.getName(),new String[]{L.t("Anulează"),L.t("Importă")},new Choice(){public void pick(int yes){if(yes==1)worker.execute(new Runnable(){public void run(){try{WebAppPackages.install(WebAppsActivity.this,zip);ui(new Runnable(){public void run(){notice(L.t("Aplicație instalată"));show();}});}catch(final Exception e){ui(new Runnable(){public void run(){notice(e.getMessage());}});}}});}});}
}
